 "content": "from collections import Counter


def transform(grid):
    """Fill cavities inside monochrome rectangular frames by area parity."""
    h = len(grid)
    if not h or not grid[0] or any(len(row) != len(grid[0]) for row in grid):
        return [row[:] for row in grid]
    w = len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    result = [row[:] for row in grid]
    frame_colors = {v for row in grid for v in row if v != background}

    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    cavity = [(y, x) for y in range(top + 1, bottom)
                              for x in range(left + 1, right)]
                    if not cavity or any(grid[y][x] != background for y, x in cavity):
                        continue
                    perimeter = ([(top, x) for x in range(left, right + 1)]
                                 + [(bottom, x) for x in range(left, right + 1)]
                                 + [(y, left) for y in range(top + 1, bottom)]
                                 + [(y, right) for y in range(top + 1, bottom)])
                    if any(all(grid[y][x] == color for y, x in perimeter)
                           for color in frame_colors):
                        fill = 7 if len(cavity) % 2 else 2
                        for y, x in cavity:
                            result[y][x] = fill
    return result


