        [8,8,8,8,8,8,8,8,8,8,9,8,8,8,8,8,8,9,8,8],
        [8,8,8,8,5,5,5,8,8,8,9,8,8,8,8,8,8,9,8,8],
        [8,8,8,8,5,8,5,8,8,8,9,8,8,8,8,8,8,9,8,8],
        [8,8,8,8,5,5,5,8,8,8,9,9,9,9,9,9,9,9,8,8],
